import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: bebasFamily } = loadBebas();



export type StackedCutTextProps = Record<string, any>;

interface CutTextLineProps {
  text: string;
  delay: number;
  textColor: string;
  frame: number;
  fps: number;
  width: number;
}

const CutTextLine: React.FC<CutTextLineProps> = ({ text, delay, textColor, frame, fps, width }) => {
  const isVisible = frame >= delay;
  
  // Spring logic for a kinetic "slam" impact when the text cuts in
  const slamSpring = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 350, mass: 0.6 }
  });

  const scale = interpolate(slamSpring, [0, 1], [1.15, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  // 2 frames of white flash for a punchy cut impact
  const isFlash = frame >= delay && frame < delay + 2;
  const color = isFlash ? "#ffffff" : textColor;

  return (
    <div
      style={{
        opacity: isVisible ? 1 : 0,
        transform: `scale(${scale})`,
        color,
        fontSize: width * 0.13,
        lineHeight: 0.85,
        fontFamily: bebasFamily,
        textAlign: 'center',
        margin: `${width * 0.015}px 0`,
        transition: 'none',
        transformOrigin: 'center center',
      }}
    >
      {text}
    </div>
  );
};

const StackedCutText: React.FC<StackedCutTextProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 5,
  textLine1 = "EVERY PLATFORM.",
  textLine2 = "EVERY TREND.",
  textLine3 = "NO STORY.",
  textColor = "#d94f04",
  staggerFrames = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Very subtle continuous global scale to keep the frame alive after cuts
  const globalScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.05]);

  const startDelay = 15;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill
        style={{
          transform: `scale(${globalScale})`,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          padding: '0 5%',
          transition: 'none',
        }}
      >
        <CutTextLine 
          text={textLine1} 
          delay={startDelay} 
          textColor={textColor} 
          frame={frame} 
          fps={fps} 
          width={width} 
        />
        <CutTextLine 
          text={textLine2} 
          delay={startDelay + staggerFrames} 
          textColor={textColor} 
          frame={frame} 
          fps={fps} 
          width={width} 
        />
        <CutTextLine 
          text={textLine3} 
          delay={startDelay + (staggerFrames * 2)} 
          textColor={textColor} 
          frame={frame} 
          fps={fps} 
          width={width} 
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default StackedCutText;